<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Где открывать счёт по контракту с бюджетом Санкт-Петербурга?", "acceptedAnswer": {"@type": "Answer", "text": "В Комитете финансов Санкт-Петербурга. Если средства идут из бюджета города и подпадают под казначейское сопровождение, лицевой счёт открывают в Комитете финансов по его порядку, а не в территориальном органе Федерального казначейства."}}, {"@type": "Question", "name": "Чем регулируется открытие счёта в Комитете финансов?", "acceptedAnswer": {"@type": "Answer", "text": "Распоряжением Комитета финансов Санкт-Петербурга от 10.02.2022 № 10-р, которое утвердило порядок открытия и ведения лицевых счетов участников казначейского сопровождения и санкционирования операций. Право города сопровождать свои средства основано на статье 242.23 Бюджетного кодекса."}}, {"@type": "Question", "name": "Нужен ли счёт с кодом 71 для контракта Санкт-Петербурга?", "acceptedAnswer": {"@type": "Answer", "text": "Нет, если деньги идут из городского бюджета. Счёт с кодом 71 открывают в территориальном органе Федерального казначейства для федеральных средств. Для средств бюджета Санкт-Петербурга счёт открывают в Комитете финансов по городскому порядку."}}, {"@type": "Question", "name": "Кто санкционирует операции по городскому счёту?", "acceptedAnswer": {"@type": "Answer", "text": "Комитет финансов Санкт-Петербурга. Он проверяет, что расход соответствует целям контракта, подтверждён документами-основаниями и содержит корректные реквизиты, включая идентификатор государственного контракта и назначение платежа. Без санкционирования платёж не проходит."}}, {"@type": "Question", "name": "Может ли у исполнителя быть и счёт 71, и счёт в Комитете финансов?", "acceptedAnswer": {"@type": "Answer", "text": "Да. По федеральному контракту исполнителю откроют счёт с кодом 71 в территориальном органе казначейства, по контракту с бюджетом Санкт-Петербурга — счёт в Комитете финансов. Это два параллельных контура, средства по ним ведут раздельно."}}, {"@type": "Question", "name": "Какие документы нужны для открытия счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Обычно это заявление на открытие лицевого счёта, карточка образцов подписей, копия документа-основания (контракта, договора, соглашения) и документы, подтверждающие полномочия подписантов. Точный состав и формы сверяйте с актуальной редакцией распоряжения № 10-р."}}, {"@type": "Question", "name": "Отличается ли петербургская модель от московской?", "acceptedAnswer": {"@type": "Answer", "text": "Принцип одинаковый: город сопровождает средства своего бюджета сам. Отличается организация: в Москве это Казначейство Москвы (Департамент финансов) и обмен через ПИВ АСУ ГФ, в Санкт-Петербурге — Комитет финансов по распоряжению № 10-р. Формы и порядок у каждого города свои."}}, {"@type": "Question", "name": "Меняет ли сопровождение налоговый статус исполнителя?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Открытие лицевого счёта в Комитете финансов не превращает коммерческую организацию в получателя бюджетных средств: она остаётся неучастником бюджетного процесса, которому открыт счёт для контроля целевых средств. Налоги исполнитель платит в обычном порядке."}}, {"@type": "Question", "name": "Как быстро проходят платежи по городскому счёту?", "acceptedAnswer": {"@type": "Answer", "text": "Каждая операция проходит санкционирование, поэтому платёж «день в день» на целевые средства планировать не стоит. Расчёты с поставщиками и подрядчиками закладывайте с учётом времени на проверку распоряжения Комитетом финансов."}}]}
</script>
